<script setup lang="ts">
import {ref,watch} from 'vue'
import {t} from '../i18n'
import {detailHost,detailID,diagnostic,diagnosticBusy,detailError,closeSiteDetails,runDiagnostics,relatedDDNS,saveSiteMetadata} from '../composables/useSiteWorkspace'
import {providers,readOnly} from '../composables/useState'
import {openEdit,webListeners} from '../composables/useHosts'
const tagText=ref(''),metadataBusy=ref(false),metadataNote=ref('')
watch(detailID,()=>{tagText.value=detailHost.value?.tags?.join(', ')||'';metadataNote.value=''})
async function saveTags(){if(!detailHost.value)return;metadataBusy.value=true;try{await saveSiteMetadata(detailHost.value,tagText.value.split(/[,，]/));metadataNote.value=t('已保存')}catch(e){metadataNote.value=e instanceof Error?e.message:t('保存失败')}finally{metadataBusy.value=false}}
</script>
<template><div v-if="detailID!==null" class="overlay detail-overlay" v-dialog><section class="modal site-detail-drawer"><div class="modal-top"><div><small>{{t('站点详情')}}</small><h2>{{detailHost?.name||detailHost?.domain}}</h2><p>{{detailHost?.domain}}</p></div><button class="icon-btn" :aria-label="t('关闭站点详情')" @click="closeSiteDetails">×</button></div>
<template v-if="detailHost"><div class="detail-actions"><button class="secondary" :disabled="readOnly" @click="openEdit(detailHost);closeSiteDetails()">{{t('编辑')}}</button><button class="primary" :disabled="diagnosticBusy" @click="runDiagnostics">{{diagnosticBusy?t('正在诊断…'):t('一键诊断')}}</button></div>
<dl class="detail-grid"><dt>{{t('监听入口')}}</dt><dd>{{webListeners.find(l=>l.id===detailHost?.listener_id)?.protocol.toUpperCase()}} :{{webListeners.find(l=>l.id===detailHost?.listener_id)?.port}}</dd><dt>{{t('服务类型')}}</dt><dd>{{detailHost.type==='static'?t('静态站点'):detailHost.type==='files'?t('文件服务'):detailHost.type==='redirect'?t('URL 重定向'):t('反向代理')}}</dd><dt>{{t('目标')}}</dt><dd>{{detailHost.root_path||detailHost.redirect_target||detailHost.upstream}}</dd><dt>{{t('访问路径')}}</dt><dd>{{detailHost.path||'/'}}</dd><dt>{{t('证书来源')}}</dt><dd>{{t(detailHost.certificate_source?.label||'暂无证书')}} {{detailHost.certificate_source?.domain}}<small v-if="detailHost.certificate_source?.not_after">{{t('到期')}} {{new Date(detailHost.certificate_source.not_after).toLocaleString()}}</small></dd><dt>{{t('DNS 凭据')}}</dt><dd>{{providers.find(p=>p.id===detailHost?.dns_provider_id)?.name||t('未直接绑定')}}</dd><dt>DDNS</dt><dd><span v-for="record in relatedDDNS" :key="record.id">{{record.name}} · {{record.last_ip||'—'}} · {{record.enabled?t('自动更新开启'):t('自动更新关闭')}}<br/></span><span v-if="!relatedDDNS.length">{{t('没有匹配的 DDNS 任务')}}</span></dd><dt>{{t('访问保护')}}</dt><dd>{{detailHost.basic_auth_enabled?'Basic Auth · ':''}}{{detailHost.security_headers?.enabled?t('安全响应头已启用'):t('安全响应头未启用')}} · {{detailHost.ip_allowlist.length}} {{t('条允许规则')}} / {{detailHost.ip_denylist.length}} {{t('条拒绝规则')}}</dd></dl>
<form class="detail-tag-form" @submit.prevent="saveTags"><label>{{t('标签（逗号分隔）')}}<input v-model="tagText" :disabled="readOnly" maxlength="260" :placeholder="t('例如：家庭, 媒体, 内网')"/></label><button class="secondary" :disabled="readOnly||metadataBusy">{{t('保存标签')}}</button><p role="status">{{metadataNote}}</p></form>
<section class="diagnostic-results"><h3>{{t('访问链路诊断')}}</h3><p class="auth-hint">{{t('从服务器检查 DNS 和本机入口；不代表已从公网验证防火墙、NAT 或 CDN。')}}</p><p v-if="diagnosticBusy" role="status">{{t('正在逐项检查，请稍候…')}}</p><p v-if="detailError" class="error" role="alert">{{detailError}}</p><small v-if="diagnostic">{{t('检查时间')}} {{new Date(diagnostic.checked_at).toLocaleString()}}</small><article v-for="step in diagnostic?.steps" :key="step.name" class="diagnostic-step" :class="step.state"><strong>{{t(step.name)}} <span>{{t(({pass:'通过',warn:'需确认',fail:'失败',info:'说明'} as Record<string,string>)[step.state])}}</span></strong><p>{{step.detail}}</p><small v-if="step.advice">{{t(step.advice)}}</small></article></section></template><p v-else class="error">{{t('站点已删除或暂不可用')}}</p>
<footer class="site-detail-footer"><button class="secondary" @click="closeSiteDetails">{{t('确认关闭')}}</button></footer></section></div></template>
